#include "conv_standard_2d_asymmetric_input_square_kernel_custom_tiling.h"
#include "register/op_def_registry.h"

namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvStandard2dAsymmetricInputSquareKernelCustomTilingData tiling;

    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);

    // Assume NCHW for x and OIHW for w, stride=1, padding=0, dilation=1, groups=1
    uint32_t N   = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(0));
    uint32_t Cin = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(1));
    uint32_t H   = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(2));
    uint32_t W   = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(3));

    uint32_t Cout = static_cast<uint32_t>(w_shape->GetOriginShape().GetDim(0));
    uint32_t K    = static_cast<uint32_t>(w_shape->GetOriginShape().GetDim(2)); // square kernel

    uint32_t Hout = H >= K ? (H - K + 1) : 0;
    uint32_t Wout = W >= K ? (W - K + 1) : 0;

    uint32_t totalOut = N * Cout * Hout * Wout;

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_n(N);
    tiling.set_cin(Cin);
    tiling.set_cout(Cout);
    tiling.set_h(H);
    tiling.set_w(W);
    tiling.set_k(K);
    tiling.set_hout(Hout);
    tiling.set_wout(Wout);
    tiling.set_totalOut(totalOut);
    tiling.set_tileNum(TILE_NUM);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}


namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);

    uint64_t N   = x_shape->GetOriginShape().GetDim(0);
    uint64_t Cin = x_shape->GetOriginShape().GetDim(1);
    uint64_t H   = x_shape->GetOriginShape().GetDim(2);
    uint64_t W   = x_shape->GetOriginShape().GetDim(3);

    uint64_t Cout = w_shape->GetOriginShape().GetDim(0);
    uint64_t Kw   = w_shape->GetOriginShape().GetDim(2); // square

    uint64_t Hout = H >= Kw ? (H - Kw + 1) : 0;
    uint64_t Wout = W >= Kw ? (W - Kw + 1) : 0;

    gert::Shape* y_shape = context->GetOutputShape(0);
    std::vector<int64_t> out_dims = { static_cast<int64_t>(N), static_cast<int64_t>(Cout),
                                      static_cast<int64_t>(Hout), static_cast<int64_t>(Wout) };
    y_shape->SetDimNum(out_dims.size());
    for (size_t i = 0; i < out_dims.size(); ++i) {
        y_shape->SetDim(i, out_dims[i]);
    }
    return GRAPH_SUCCESS;
}

