#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include \"pytorch_npu_helper.hpp\"
#include <torch/extension.h>

at::Tensor conv_standard_2d_asymmetric_input_square_kernel_custom_impl_npu(const at::Tensor& x, const at::Tensor& w) {
    TORCH_CHECK(x.dim() == 4, \"x must be NCHW\");
    TORCH_CHECK(w.dim() == 4, \"w must be OIHW\");
    TORCH_CHECK(x.scalar_type() == at::kFloat, \"only float32 supported\");
    TORCH_CHECK(w.scalar_type() == at::kFloat, \"only float32 supported\");
    TORCH_CHECK(x.size(1) == w.size(1), \"in_channels mismatch\");

    // stride=1, pad=0, dilation=1
    auto N = x.size(0);
    auto Cin = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);
    auto Cout = w.size(0);
    auto K = w.size(2); // square

    TORCH_CHECK(w.size(2) == w.size(3), \"kernel must be square\");
    TORCH_CHECK(H >= K && W >= K, \"input smaller than kernel for stride=1, pad=0\");

    auto Hout = H - K + 1;
    auto Wout = W - K + 1;

    at::Tensor y = at::empty({N, Cout, Hout, Wout}, x.options());
    EXEC_NPU_CMD(aclnnConvStandard2dAsymmetricInputSquareKernelCustom, x, w, y);
    return y;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl(\"conv_standard_2d_asymmetric_input_square_kernel_custom\", &conv_standard_2d_asymmetric_input_square_kernel_custom_impl_npu);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(\"conv_standard_2d_asymmetric_input_square_kernel_custom\", &conv_standard_2d_asymmetric_input_square_kernel_custom_impl_npu, \"2D conv (square kernel, stride=1, pad=0)\");
}
